import { expect, test } from '../../fixtures/billing';
import { PERIOD_END, projects } from '../../fixtures/testData';

test('BR-04 each line is converted and rounded to the customer\'s currency before its tax is worked out, and the total adds up the rounded lines @critical', async ({ proposal }) => {
  await proposal.create(projects.polarCloseout, PERIOD_END);

  await expect(proposal.page.locator('#proposal-currency')).toHaveText('USD');
  await expect(proposal.page.locator('#proposal-rate')).toHaveText('1.0835');
  await expect(proposal.lines).toHaveCount(1);

  // 42.50 EUR at 1.0835 is 46.04875 USD; the line is rounded first and VAT is worked out on 46.05.
  await expect(proposal.amountOf(1)).toHaveText('46.05');
  await expect(proposal.line(1).locator('.line-tax')).toHaveText('11.74');

  // The total is the sum of the rounded line and its tax.
  await expect(proposal.subtotal).toHaveText('46.05');
  await expect(proposal.tax).toHaveText('11.74');
  await expect(proposal.total).toHaveText('57.79 USD');

  proposal.page.once('dialog', (dialog) => dialog.accept());
  await proposal.page.locator('#delete-proposal').click();
});
